# Release at the measured pose, withdraw from the rim, and return both arms to origin together.
s = get_observation()['state']
for i in range(10):
    a = {k:v for k,v in s.items() if k.endswith('joint_state')}
    a['right_ee_joint_state'] = [1]
    if not controlled_step(a):
        break
move('right',[0.25,-0.065,1.05],qforward,1,10,speed=0.025,settle=2)
s = get_observation()['state']
lstart = np.array(s['left_arm_joint_state']).copy()
rstart = np.array(s['right_arm_joint_state']).copy()
for i in range(min(32,control_remaining)):
    f = max(0.0,1.0-(i+1)/25.0)
    a = {'left_arm_joint_state':lstart*f,'right_arm_joint_state':rstart*f,'left_ee_joint_state':[1],'right_ee_joint_state':[1]}
    if not controlled_step(a):
        break
print('Final state',get_observation()['state'])
print('remaining',control_remaining,'done',done)

